UPDATE documents
SET content = content || E'\n\n[h2]13. Удаление неактивных аккаунтов[/h2]\nЕсли Пользователь не входил в Приложение в течение 30 (тридцати) календарных дней подряд, Разработчик оставляет за собой право удалить такую учетную запись без предварительного уведомления. Все данные пользователя будут безвозвратно удалены. Пользователь может предотвратить удаление, просто войдя в Приложение до истечения указанного срока.\n',
    version = '1.1'
WHERE type = 'user_agreement' AND version = '1.0';

UPDATE documents
SET content = content || E'\n\n[h2]7.3. Удаление неактивных аккаунтов[/h2]\nВ целях оптимизации хранения данных и защиты конфиденциальности, если Пользователь не авторизовывался в Приложении более 30 (тридцати) дней подряд, его персональные данные и вся связанная с ним информация могут быть удалены. О таком удалении Разработчик может не уведомлять пользователя заранее. Пользователь может избежать удаления, осуществляя вход в Приложение не реже одного раза в 30 дней.\n',
    version = '1.1'
WHERE type = 'privacy_policy' AND version = '1.0';

UPDATE documents
SET content = content || E'\n\n[h2]13. Удаление неактивных профилей[/h2]\nДля поддержания актуальности базы пользователей и повышения качества знакомств, профили, владельцы которых не входили в приложение в течение 30 (тридцати) дней, могут быть автоматически удалены. Если Вы хотите сохранить свой профиль, пожалуйста, заходите в приложение не реже одного раза в месяц. Восстановление удалённого из‑за неактивности профиля невозможно.\n',
    version = '1.1'
WHERE type = 'community_rules' AND version = '1.0';